  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  7→};
  8→
  9→serve(async (req) => {
 10→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 11→
 12→  try {
 13→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 14→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
 15→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 16→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 17→
 18→    if (!DODO_API_KEY) {
 19→      return new Response(JSON.stringify({ error: "Dodo Payments API key not configured" }), {
 20→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
 21→      });
 22→    }
 23→
 24→    // Authenticate user
 25→    const authHeader = req.headers.get("Authorization");
 26→    if (!authHeader) {
 27→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 28→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 29→      });
 30→    }
 31→
 32→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
 33→      global: { headers: { Authorization: authHeader } },
 34→    });
 35→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 36→    if (userError || !user) {
 37→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 38→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 39→      });
 40→    }
 41→
 42→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 43→    const body = await req.json();
 44→    const { pack_id, plan_id, return_url } = body;
 45→
 46→    if (!pack_id && !plan_id) {
 47→      return new Response(JSON.stringify({ error: "pack_id or plan_id required" }), {
 48→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 49→      });
 50→    }
 51→
 52→    let productId: string;
 53→    let amount: number;
 54→    let credits: number;
 55→    let currency = "USD";
 56→    let itemName: string;
 57→
 58→    if (pack_id) {
 59→      const { data: pack, error } = await supabase
 60→        .from("credit_packs")
 61→        .select("*")
 62→        .eq("id", pack_id)
 63→        .eq("active", true)
 64→        .single();
 65→      if (error || !pack) {
 66→        return new Response(JSON.stringify({ error: "Credit pack not found or inactive" }), {
 67→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
 68→        });
 69→      }
 70→      if (!pack.dodo_product_id) {
 71→        return new Response(JSON.stringify({ error: "This pack is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
 72→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 73→        });
 74→      }
 75→      productId = pack.dodo_product_id;
 76→      amount = Math.round(pack.price * 100);
 77→      credits = pack.credits;
 78→      itemName = pack.name;
 79→    } else {
 80→      const { data: plan, error } = await supabase
 81→        .from("plans")
 82→        .select("*")
 83→        .eq("id", plan_id)
 84→        .eq("active", true)
 85→        .single();
 86→      if (error || !plan) {
 87→        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
 88→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
 89→        });
 90→      }
 91→      if (!plan.dodo_product_id) {
 92→        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
 93→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 94→        });
 95→      }
 96→      productId = plan.dodo_product_id;
 97→      amount = Math.round(plan.price * 100);
 98→      credits = plan.credits;
 99→      itemName = plan.name;
100→    }
101→
102→    // Build return URL
103→    const baseReturnUrl = return_url || `${req.headers.get("origin") || "https://instantresumeranker.lovable.app"}/payment/callback`;
104→
105→    // Create Dodo Payments checkout session
106→    const dodoRes = await fetch("https://live.dodopayments.com/payments", {
107→      method: "POST",
108→      headers: {
109→        "Authorization": `Bearer ${DODO_API_KEY}`,
110→        "Content-Type": "application/json",
111→      },
112→      body: JSON.stringify({
113→        billing: {
114→          city: "NA",
115→          country: "US",
116→          state: "NA",
117→          street: "NA",
118→          zipcode: "00000",
119→        },
120→        customer: {
121→          email: user.email,
122→          name: user.email?.split("@")[0] || "Customer",
123→        },
124→        payment_link: true,
125→        product_cart: [
126→          { product_id: productId, quantity: 1 },
127→        ],
128→        return_url: baseReturnUrl,
129→      }),
130→    });
131→
132→    if (!dodoRes.ok) {
133→      const errText = await dodoRes.text();
134→      console.error("Dodo API error:", dodoRes.status, errText);
135→      return new Response(JSON.stringify({ error: `Dodo Payments error: ${errText.slice(0, 200)}` }), {
136→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
137→      });
138→    }
139→
140→    const dodoData = await dodoRes.json();
141→    const checkoutUrl = dodoData.payment_link;
142→    const paymentId = dodoData.payment_id;
143→
144→    // Insert payment record
145→    await supabase.from("payments").insert({
146→      user_id: user.id,
147→      amount,
148→      currency,
149→      credits_purchased: credits,
150→      status: "created",
151→      payment_gateway: "dodo",
152→      dodo_payment_id: paymentId,
153→      ...(pack_id ? { pack_id } : { plan_id }),
154→    });
155→
156→    return new Response(JSON.stringify({
157→      checkout_url: checkoutUrl,
158→      payment_id: paymentId,
159→    }), {
160→      headers: { ...corsHeaders, "Content-Type": "application/json" },
161→    });
162→  } catch (err: unknown) {
163→    console.error("create-dodo-checkout error:", err);
164→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
165→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
166→    });
167→  }
168→});
