35→    if (userError || !user) {
36→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
37→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
38→      });
39→    }
40→
41→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
42→
43→    // Get user's dodo subscription ID
44→    const { data: profile } = await supabase
45→      .from("profiles")
46→      .select("dodo_subscription_id")
47→      .eq("user_id", user.id)
48→      .single();
49→
50→    if (!profile?.dodo_subscription_id) {
51→      return new Response(JSON.stringify({ error: "No active Dodo subscription found" }), {
52→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
53→      });
54→    }
55→
56→    // Cancel subscription via Dodo API
57→    const dodoRes = await fetch(
58→      `https://live.dodopayments.com/subscriptions/${profile.dodo_subscription_id}`,
59→      {
60→        method: "PATCH",
61→        headers: {
62→          "Authorization": `Bearer ${DODO_API_KEY}`,
63→          "Content-Type": "application/json",
64→        },
65→        body: JSON.stringify({ status: "cancelled" }),
66→      }
67→    );
68→
69→    if (!dodoRes.ok) {
70→      const errText = await dodoRes.text();
71→      console.error("Dodo cancel error:", dodoRes.status, errText);
72→      return new Response(JSON.stringify({ error: `Failed to cancel: ${errText.slice(0, 200)}` }), {
73→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
74→      });
75→    }
76→
77→    // Update profile — subscription will remain active until end of period
78→    // The webhook will handle the final downgrade
79→
80→    return new Response(JSON.stringify({ success: true, message: "Subscription will cancel at end of billing period" }), {
81→      headers: { ...corsHeaders, "Content-Type": "application/json" },
