 1→import { useEffect, useState } from "react";
 2→import { useNavigate, useSearchParams } from "react-router-dom";
 3→import { useAuth } from "@/hooks/useAuth";
 4→import { Card, CardContent } from "@/components/ui/card";
 5→import { Button } from "@/components/ui/button";
 6→import { CheckCircle2, XCircle, Loader2 } from "lucide-react";
 7→
 8→const PaymentCallback = () => {
 9→  const [searchParams] = useSearchParams();
10→  const navigate = useNavigate();
11→  const { refreshProfile } = useAuth();
12→  const [status, setStatus] = useState<"loading" | "success" | "failed">("loading");
13→
14→  useEffect(() => {
15→    const paymentStatus = searchParams.get("status");
16→    // Dodo may redirect with different param names
17→    const dodoPaid = searchParams.get("payment_status");
18→
19→    if (paymentStatus === "failed" || dodoPaid === "failed") {
20→      setStatus("failed");
21→    } else {
22→      // Default to success — webhook will confirm payment
23→      setStatus("success");
24→      refreshProfile();
25→    }
26→
27→    // Auto-redirect after 5 seconds
28→    const timer = setTimeout(() => {
29→      navigate("/", { replace: true });
30→    }, 5000);
31→
32→    return () => clearTimeout(timer);
33→  }, [searchParams, navigate, refreshProfile]);
34→
35→  return (
36→    <div className="min-h-screen flex items-center justify-center bg-background p-4">
37→      <Card className="w-full max-w-md">
38→        <CardContent className="pt-8 pb-8 text-center space-y-4">
39→          {status === "loading" && (
40→            <>
41→              <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto" />
42→              <h2 className="text-xl font-semibold text-foreground">Processing payment…</h2>
43→              <p className="text-sm text-muted-foreground">Please wait while we confirm your payment.</p>
44→            </>
45→          )}
46→          {status === "success" && (
47→            <>
48→              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-primary/10">
49→                <CheckCircle2 className="h-8 w-8 text-primary" />
50→              </div>
51→              <h2 className="text-xl font-semibold text-foreground">Payment Successful!</h2>
52→              <p className="text-sm text-muted-foreground">
53→                Your credits will be added shortly. Redirecting to dashboard…
54→              </p>
55→              <Button variant="outline" onClick={() => navigate("/", { replace: true })}>
56→                Go to Dashboard Now
57→              </Button>
58→            </>
59→          )}
60→          {status === "failed" && (
61→            <>
