366→            <AlertDialogTitle>
367→              {confirmAction?.type === "upgrade"
368→                ? `Subscribe to ${confirmAction.planName}?`
369→                : confirmAction?.type === "cancel_subscription"
370→                  ? "Cancel Auto-Renewal?"
371→                  : "Switch to Pay As You Go?"}
372→            </AlertDialogTitle>
373→            <AlertDialogDescription>
374→              {confirmAction?.type === "upgrade" ? (
375→                <>
376→                  You'll be redirected to our secure checkout page to complete payment of{" "}
377→                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
378→                  Your subscription will auto-renew each billing period.
379→                </>
380→              ) : confirmAction?.type === "cancel_subscription" ? (
381→                <>
382→                  Your subscription will remain active until the end of your current billing period.
383→                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
384→                </>
385→              ) : (
386→                <>
387→                  You'll switch back to Pay As You Go pricing at <span className="font-semibold text-foreground">${paygCost}/resume</span>.
388→                  Your remaining credits will be preserved and you can still purchase credit top-ups.
389→                  {hasActiveSubscription && " Your active subscription will also be cancelled."}
390→                </>
391→              )}
392→            </AlertDialogDescription>
393→          </AlertDialogHeader>
394→          <AlertDialogFooter>
395→            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
396→            <AlertDialogAction
397→              onClick={handleConfirmedAction}
398→              disabled={downgrading || cancelling}
399→              className={confirmAction?.type !== "upgrade" ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
400→            >
401→              {(downgrading || cancelling) && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
402→              {confirmAction?.type === "upgrade"
403→                ? "Proceed to Payment"
404→                : confirmAction?.type === "cancel_subscription"
405→                  ? "Cancel Auto-Renewal"
406→                  : "Confirm Downgrade"}
407→            </AlertDialogAction>
408→          </AlertDialogFooter>
409→        </AlertDialogContent>
410→      </AlertDialog>
411→    </>
412→  );
413→};
414→
415→export default SubscriptionDialog;
