 16→
 17→const PlansTab = () => {
 18→  const qc = useQueryClient();
 19→  const [syncing, setSyncing] = useState<string | null>(null);
 20→  const [syncingAll, setSyncingAll] = useState(false);
 21→  const [saving, setSaving] = useState(false);
 22→  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);
 23→
 24→  const { data: plans } = useQuery({
 25→    queryKey: ["admin_plans"],
 26→    queryFn: async () => {
 27→      const { data, error } = await supabase.from("plans").select("*").order("created_at");
 28→      if (error) throw error;
 29→      return data;
 30→    },
 31→  });
 32→
 33→  const [editPlan, setEditPlan] = useState<any>(null);
 34→  const [form, setForm] = useState({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", dodo_product_id: "" });
 35→
 36→  const openNew = () => {
 37→    setForm({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", dodo_product_id: "" });
 38→    setEditPlan("new");
 39→  };
 40→
 41→  const openEdit = (p: any) => {
 42→    setForm({ name: p.name, price: String(p.price), credits: String(p.credits), billing_type: p.billing_type, active: p.active, per_resume_cost: String(p.per_resume_cost ?? 0.05), dodo_product_id: (p as any).dodo_product_id || "" });
 43→    setEditPlan(p);
 44→  };
 45→
 46→  const validate = () => {
 47→    if (!form.name.trim()) { toast.error("Plan name is required"); return false; }
 48→    if (!form.price || parseFloat(form.price) <= 0) { toast.error("Price must be greater than 0"); return false; }
 49→    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
 50→    if (parseFloat(form.per_resume_cost) < 0) { toast.error("Per resume cost cannot be negative"); return false; }
 51→    return true;
 52→  };
 53→
 54→  const save = async () => {
 55→    if (!validate()) return;
 56→    setSaving(true);
 57→    try {
 58→      const priceChanged = editPlan !== "new" && parseFloat(form.price) !== editPlan.price;
 59→      const payload = {
 60→        name: form.name.trim(),
 61→        price: parseFloat(form.price),
 62→        credits: parseInt(form.credits),
 63→        billing_type: form.billing_type,
 64→        active: form.active,
 65→        per_resume_cost: parseFloat(form.per_resume_cost),
 66→        dodo_product_id: form.dodo_product_id.trim() || null,
 67→        ...(priceChanged ? { razorpay_plan_id: null } : {}),
 68→      } as any;
 69→
 70→      if (editPlan === "new") {
 71→        const { error } = await supabase.from("plans").insert(payload);
 72→        if (error) { toast.error(error.message); return; }
 73→      } else {
 74→        const { error } = await supabase.from("plans").update(payload).eq("id", editPlan.id);
 75→        if (error) { toast.error(error.message); return; }
 76→        if (priceChanged) toast.info("Price changed — Razorpay sync required");
 77→      }
 78→      toast.success("Plan saved");
