 83→        { name: form.name, price: form.price, credits: form.credits },
 84→      );
 85→      qc.invalidateQueries({ queryKey: ["admin_plans"] });
 86→      setEditPlan(null);
 87→    } finally {
 88→      setSaving(false);
 89→    }
 90→  };
 91→
 92→  const confirmDelete = async () => {
 93→    if (!deleteTarget) return;
