102→  const syncToRazorpay = async (planId: string) => {
103→    setSyncing(planId);
104→    try {
105→      // Clear existing razorpay_plan_id first so a fresh one is created
106→      await supabase.from("plans").update({ razorpay_plan_id: null } as any).eq("id", planId);
107→      const { data, error } = await supabase.functions.invoke("create-razorpay-plan", {
108→        body: { plan_id: planId },
109→      });
110→      if (error) throw error;
111→      toast.success(`Synced to Razorpay: ${data.razorpay_plan_id}`);
112→      qc.invalidateQueries({ queryKey: ["admin_plans"] });
113→    } catch (err: any) {
114→      toast.error("Sync failed: " + err.message);
115→    } finally {
116→      setSyncing(null);
117→    }
118→  };
119→
120→  
121→  const syncAllToRazorpay = async () => {
122→    if (!plans?.length) return;
123→    setSyncingAll(true);
124→    let success = 0;
125→    let failed = 0;
126→    for (const p of plans.filter((p: any) => p.active)) {
127→      try {
128→        await supabase.from("plans").update({ razorpay_plan_id: null } as any).eq("id", p.id);
129→        const { error } = await supabase.functions.invoke("create-razorpay-plan", {
130→          body: { plan_id: p.id },
131→        });
132→        if (error) throw error;
133→        success++;
134→      } catch {
135→        failed++;
136→      }
137→    }
138→    qc.invalidateQueries({ queryKey: ["admin_plans"] });
139→    toast.success(`Re-synced ${success} plans${failed ? `, ${failed} failed` : ""}`);
140→    setSyncingAll(false);
141→  };
142→
143→  return (
144→    <>
145→      <Card>
