149→        </div>
150→        <div className="flex items-center gap-2">
151→          <Button size="sm" variant="outline" onClick={syncAllToRazorpay} disabled={syncingAll || !!syncing}>
152→            {syncingAll ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <RefreshCw className="h-4 w-4 mr-1" />}
153→            Re-sync All
154→          </Button>
155→          <Dialog open={editPlan !== null} onOpenChange={(o) => !o && setEditPlan(null)}>
156→            <DialogTrigger asChild>
157→              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Plan</Button>
158→            </DialogTrigger>
159→            <DialogContent>
160→              <DialogHeader><DialogTitle>{editPlan === "new" ? "New Plan" : "Edit Plan"}</DialogTitle></DialogHeader>
161→              <div className="space-y-3">
162→                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Pro Monthly" /></div>
163→                <div className="grid grid-cols-2 gap-3">
164→                  <div><Label>Price ($)</Label><Input type="number" min="0.01" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
165→                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
166→                </div>
