172→                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
173→                <Button onClick={save} className="w-full" disabled={saving}>
174→                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
175→                  Save
176→                </Button>
177→              </div>
178→            </DialogContent>
179→          </Dialog>
180→        </div>
181→        </CardHeader>
182→        <CardContent className="p-0">
183→          <Table>
