  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  7→};
  8→
  9→serve(async (req) => {
 10→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 11→
 12→  try {
 13→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 14→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 15→    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
 16→
 17→    const authHeader = req.headers.get("Authorization");
 18→    if (!authHeader) throw new Error("No auth");
 19→
 20→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 21→      global: { headers: { Authorization: authHeader } },
 22→    });
 23→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 24→    if (userError || !user) throw new Error("Unauthorized");
 25→    const userId = user.id;
 26→
 27→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 28→
 29→    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
 30→    if (!roles?.some((r: any) => r.role === "admin")) {
 31→      return new Response(JSON.stringify({ error: "Admin access required" }), {
 32→        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
 33→      });
 34→    }
 35→
 36→    const body = await req.json();
 37→    const { key_name } = body;
 38→
 39→    // ─── DNS MX record check ───
 40→    if (key_name === "DNS_MX_CHECK") {
 41→      const domain = body.domain;
 42→      if (!domain) throw new Error("Missing domain");
 43→
 44→      try {
 45→        // Use Google DNS-over-HTTPS API to check MX records
 46→        const dnsRes = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`);
 47→        const dnsData = await dnsRes.json();
 48→
 49→        const mxRecords: { exchange: string; priority: number }[] = [];
 50→        let pointsToPostmark = false;
 51→
 52→        if (dnsData.Answer && Array.isArray(dnsData.Answer)) {
 53→          for (const answer of dnsData.Answer) {
 54→            if (answer.type === 15) { // MX record type
 55→              const parts = answer.data.split(" ");
 56→              const priority = parseInt(parts[0], 10);
 57→              const exchange = (parts[1] || "").replace(/\.$/, "").toLowerCase();
 58→              mxRecords.push({ exchange, priority });
 59→              if (exchange.includes("inbound.postmarkapp.com")) {
 60→                pointsToPostmark = true;
 61→              }
 62→            }
 63→          }
 64→        }
 65→
 66→        return new Response(JSON.stringify({
 67→          status: mxRecords.length > 0 ? "success" : "no_records",
 68→          domain,
 69→          mx_records: mxRecords,
 70→          points_to_postmark: pointsToPostmark,
 71→        }), {
 72→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 73→        });
 74→      } catch (e: unknown) {
 75→        return new Response(JSON.stringify({
 76→          status: "error",
 77→          error: e instanceof Error ? e.message : String(e),
 78→        }), {
 79→          headers: { ...corsHeaders, "Content-Type": "application/json" },
 80→        });
 81→      }
 82→    }
 83→
 84→    if (!key_name) throw new Error("Missing key_name");
 85→
 86→    let status = "failed";
 87→    let errorMsg = "";
 88→    let details: Record<string, any> = {};
 89→
 90→    if (key_name === "OPENAI_API_KEY") {
 91→      const openaiKey = Deno.env.get("OPENAI_API_KEY");
 92→      if (!openaiKey) {
 93→        errorMsg = "OPENAI_API_KEY secret is not configured";
 94→      } else {
 95→        try {
 96→          const res = await fetch("https://api.openai.com/v1/models", {
 97→            headers: { Authorization: `Bearer ${openaiKey}` },
 98→          });
 99→          if (res.ok) {
100→            status = "success";
101→          } else {
102→            const body = await res.text();
103→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
104→          }
105→        } catch (e: unknown) {
106→          errorMsg = e instanceof Error ? e.message : String(e);
107→        }
108→      }
109→    } else if (key_name === "RAZORPAY_KEY_ID") {
110→      const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID");
111→      const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
112→      if (!razorpayKeyId || !razorpayKeySecret) {
113→        errorMsg = "RAZORPAY_KEY_ID or RAZORPAY_KEY_SECRET secret is not configured";
114→      } else {
115→        try {
116→          const res = await fetch("https://api.razorpay.com/v1/payments?count=1", {
117→            headers: {
118→              Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
119→            },
120→          });
121→          if (res.ok) {
122→            status = "success";
123→          } else {
124→            const body = await res.text();
125→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
126→          }
127→        } catch (e: unknown) {
128→          errorMsg = e instanceof Error ? e.message : String(e);
129→        }
130→      }
131→    } else if (key_name === "POSTMARK_API_TOKEN") {
132→      // Read token from platform_config (stored in DB, not env vars)
133→      const { data: config } = await supabase
134→        .from("platform_config")
135→        .select("postmark_api_token, email_from_address")
136→        .limit(1)
137→        .single();
138→
139→      const apiToken = config?.postmark_api_token;
140→      if (!apiToken) {
141→        errorMsg = "Postmark API token is not configured. Add it in Email Settings.";
142→      } else {
143→        try {
144→          // 1. Validate token by calling /server endpoint
145→          const serverRes = await fetch("https://api.postmarkapp.com/server", {
146→            headers: {
147→              "Accept": "application/json",
148→              "X-Postmark-Server-Token": apiToken,
149→            },
150→          });
151→          const serverBody = await serverRes.text();
152→
153→          if (!serverRes.ok) {
154→            errorMsg = `Invalid API token (${serverRes.status})`;
155→            details.tokenValid = false;
156→          } else {
157→            details.tokenValid = true;
158→            try {
159→              const serverData = JSON.parse(serverBody);
160→              details.serverName = serverData.Name || "";
161→              // DeliveryType tells us about account status
162→              details.deliveryType = serverData.DeliveryType || "";
163→            } catch { /* ignore parse errors */ }
164→
165→            // 2. Check sender signatures to see if configured sender is verified
166→            const fromEmail = config?.email_from_address || "noreply@rankora.co";
167→            details.fromEmail = fromEmail;
168→
169→            const sigRes = await fetch("https://api.postmarkapp.com/sender-signatures?count=100&offset=0", {
170→              headers: {
171→                "Accept": "application/json",
172→                "X-Postmark-Server-Token": apiToken,
173→              },
174→            });
175→            const sigBody = await sigRes.text();
176→
177→            if (sigRes.ok) {
178→              try {
179→                const sigData = JSON.parse(sigBody);
180→                const senders = sigData.SenderSignatures || [];
181→                const fromDomain = fromEmail.split("@")[1]?.toLowerCase();
182→
183→                // Check if sender email or domain is verified
184→                const senderMatch = senders.find((s: any) =>
185→                  s.EmailAddress?.toLowerCase() === fromEmail.toLowerCase() ||
186→                  s.Domain?.toLowerCase() === fromDomain
187→                );
188→
189→                if (senderMatch) {
190→                  details.senderVerified = senderMatch.Confirmed === true;
191→                  details.senderName = senderMatch.Name || senderMatch.EmailAddress || "";
192→                } else {
193→                  details.senderVerified = false;
194→                  details.senderName = "";
195→                }
196→
197→                details.totalSenders = senders.length;
198→              } catch { details.senderVerified = false; }
199→            } else {
200→              details.senderVerified = false;
201→            }
202→
203→            // 3. Test actual sending capability by checking account restrictions
204→            // Try sending to a test endpoint to detect 412 (pending approval)
205→            const testRes = await fetch("https://api.postmarkapp.com/email", {
206→              method: "POST",
207→              headers: {
208→                "Accept": "application/json",
209→                "Content-Type": "application/json",
210→                "X-Postmark-Server-Token": apiToken,
211→              },
212→              body: JSON.stringify({
213→                From: fromEmail,
214→                To: "test-probe@example.com",
215→                Subject: "Connection test",
216→                TextBody: "test",
217→              }),
218→            });
219→            const testBody = await testRes.text();
220→
221→            try {
222→              const testData = JSON.parse(testBody);
223→              if (testData.ErrorCode === 412) {
224→                details.accountApproved = false;
225→                details.accountMessage = "Account is pending approval. You can only send to same-domain recipients.";
226→              } else if (testData.ErrorCode === 0 || testRes.ok) {
227→                details.accountApproved = true;
228→              } else if (testData.ErrorCode === 300) {
229→                // Sender signature not found but account may be approved
230→                details.accountApproved = true;
231→                details.senderVerified = false;
232→              } else {
233→                details.accountApproved = true; // Other errors don't mean account is pending
234→              }
235→            } catch {
236→              details.accountApproved = true;
237→            }
238→
239→            status = "success";
240→          }
241→        } catch (e: unknown) {
242→          errorMsg = e instanceof Error ? e.message : String(e);
243→        }
244→      }
245→    } else if (key_name === "DODO_PAYMENTS_API_KEY") {
246→      const dodoKey = Deno.env.get("DODO_PAYMENTS_API_KEY");
247→      if (!dodoKey) {
248→        errorMsg = "DODO_PAYMENTS_API_KEY secret is not configured";
249→      } else {
250→        try {
251→          const res = await fetch("https://live.dodopayments.com/payments?page_size=1", {
252→            headers: { Authorization: `Bearer ${dodoKey}` },
253→          });
254→          if (res.ok) {
255→            status = "success";
256→          } else {
257→            const body = await res.text();
258→            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
259→          }
260→        } catch (e: unknown) {
261→          errorMsg = e instanceof Error ? e.message : String(e);
262→        }
263→      }
264→    } else {
265→      errorMsg = `Unknown integration: ${key_name}`;
266→    }
267→
268→    // Update integrations table
269→    await supabase.from("integrations").update({
270→      last_tested_at: new Date().toISOString(),
271→      last_test_status: status,
272→      is_configured: status === "success",
273→    }).eq("key_name", key_name);
274→
275→    return new Response(JSON.stringify({ status, error: errorMsg || undefined, details }), {
276→      headers: { ...corsHeaders, "Content-Type": "application/json" },
277→    });
278→  } catch (err: unknown) {
279→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
280→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
281→    });
282→  }
283→});
